public class TokenService(TimeProvider time)
{
    public bool IsExpired(Token t) => time.GetUtcNow() >= t.ExpiresAt;
}

[Fact]
public void Token_ExpiresAfterOneHour()
{
    var time = new FakeTimeProvider(DateTimeOffset.Parse("2026-01-01T10:00Z"));
    var sut = new TokenService(time);
    var token = new Token(ExpiresAt: time.GetUtcNow().AddHours(1));

    time.Advance(TimeSpan.FromHours(1));

    Assert.True(sut.IsExpired(token));
}

